export class RefCounted {
    #refCount = 0;
    get refCount() {
        return this.#refCount;
    }
    ref() {
        this.#refCount++;
        return this;
    }
    unref() {
        if (this.#refCount > 0)
            this.#refCount--;
    }
    [Symbol.dispose]() {
        this.unref();
    }
}
